```javascript
import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const timelines = [];
  const geoms = [];
  const mats = [];

  // Extract text content with fallbacks to spec defaults
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const captionItem = items.find(item => item.role === 'caption') || {
    text: "NOVA ATELIER / CALIBRE PROGRAM",
    typography: { fontSize: 18 }
  };
  const heroItem = items.find(item => item.role === 'hero') || {
    text: "TIME, MACHINED.",
    typography: { fontSize: 124 }
  };
  const subheadItem = items.find(item => item.role === 'subhead') || {
    text: "Every calibre begins as a solid billet.",
    typography: { fontSize: 40 }
  };

  // Backdrop plane with dark-first stage
  const backdropGeom = new PlaneGeometry(7, 5.5);
  const backdropMat = new MeshBasicNodeMaterial({
    color: 0x0b0b10
  });
  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  backdropMesh.position.z = -1.5;
  group.add(backdropMesh);
  geoms.push(backdropGeom);
  mats.push(backdropMat);

  // Hero text group with per-word z-depth parallax
  const heroGroup = new Group();
  heroGroup.position.y = 0.4;

  const heroText = heroItem.text || "TIME, MACHINED.";
  const words = heroText.split(' ');
  const zOffsets = [0.12, 0.0, -0.12];
  const heroFontSize = heroItem.typography?.fontSize || 124;

  words.forEach((word, idx) => {
    const wordMesh = ctx.fontAtlas.createText(word, {
      fontSize: heroFontSize,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: -heroFontSize * 0.01
    });
    wordMesh.position.z = zOffsets[idx % zOffsets.length];
    heroGroup.add(wordMesh);
  });

  group.add(heroGroup);

  // Apply kinetic-text primitive for staggered entrance
  let kineticCleanup = null;
  const kineticResult = ctx.primitives['kinetic-text'](heroGroup, {
    staggerMs: 60,
    riseUnits: 0.35
  });
  if (kineticResult) {
    if (kineticResult.timeline) timelines.push(kineticResult.timeline);
    if (kineticResult.cleanup) kineticCleanup = kineticResult.cleanup;
  }

  // Calculate timing for dependent animations
  // Estimate: 700ms base + 60ms stagger per character + 120ms offset before underline
  const estimatedHeroAnimationDuration = 0.7 + (heroText.length - 1) * 0.06;
  const underlineStartTime = estimatedHeroAnimationDuration + 0.12;

  // Accent underline: emissive red plane, scaleX 0→1 from left
  const underlineGeom = new PlaneGeometry(2.6, 0.045);
  underlineGeom.translate(1.3, 0, 0); // Anchor to left edge
  const underlineMat = new MeshBasicNodeMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.2
  });
  const underlineMesh = new Mesh(underlineGeom, underlineMat);
  underlineMesh.position.y = -0.05;
  underlineMesh.scale.x = 0;
  group.add(underlineMesh);
  geoms.push(underlineGeom);
  mats.push(underlineMat);

  // Animate underline: grow rightward over 500ms
  const underlineTl = gsap.timeline();
  underlineTl.to(underlineMesh.scale, {
    x: 1,
    duration: 0.5,
    ease: "cubic-bezier(0.25,0.46,0.45,0.94)"
  }, underlineStartTime);
  timelines.push(underlineTl);

  // Subhead text: fade-up (opacity 0→1, y +0.2→0)
  const subheadText = subheadItem.text || "Every calibre begins as a solid billet.";
  const subheadMesh = ctx.fontAtlas.createText(subheadText, {
    fontSize: subheadItem.typography?.fontSize || 40,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: (subheadItem.typography?.fontSize || 40) * 0.02
  });
  subheadMesh.position.y = -0.65 + 0.2;
  subheadMesh.traverse(child => {
    if (child.material) {
      child.material.transparent = true;
      child.material.opacity = 0;
    }
  });
  group.add(subheadMesh);

  // Animate subhead: fade in and translate down
  const subheadTl = gsap.timeline();
  subheadTl.to(subheadMesh.position, {
    y: -0.65,
    duration: 0.5,
    ease: "cubic-bezier(0.25,0.46,0.45,0.94)"
  }, underlineStartTime);

  subheadMesh.traverse(child => {
    if (child.material) {
      subheadTl.to(child.material, {
        opacity: 1,
        duration: 0.5,
        ease: "cubic-bezier(0.25,0.46,0.45,0.94)"
      }, underlineStartTime);
    }
  });
  timelines.push(subheadTl);

  // Caption text: uppercase kicker
  const captionText = captionItem.text || "NOVA ATELIER / CALIBRE PROGRAM";
  const captionMesh = ctx.fontAtlas.createText(captionText, {
    fontSize: captionItem.typography?.fontSize || 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: (captionItem.typography?.fontSize || 18) * 0.12
  });
  captionMesh.position.y = 1.15;
  group.add(captionMesh);

  // Cleanup: dispose geometries, materials, kill timelines, and invoke primitive cleanup
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl?.kill?.());
    geoms.forEach(geom => geom?.dispose?.());
    mats.forEach(mat => mat?.dispose?.());
    if (kineticCleanup) {
      kineticCleanup();
    }
  };

  group.userData.handlers = {};

  return group;
}
